R=Path(__file__).parent; D=R/'dist';D.mkdir(exist_ok=True)
NAV=[('brand','The Brand'),('identity','Identity'),('graphics','Graphic Language'),('experience','Experience'),('applications','Applications'),('toolkit','Toolkit')]
def intro(n,label,title,body):
 return f'<header class="chapter-head"><p class="eyebrow">{n} / {label}</p><div><h1>{title}</h1><p class="intro">{body}</p></div></header>'
def section(id,kicker,title,body,cls=''):
 return f'<section id="{id}" class="guide-section {cls}"><div class="section-label"><span class="eyebrow">{kicker}</span><h2>{title}</h2></div><div class="section-body">{body}</div></section>'
def image(name,alt,cls=''):
 return f'<img class="{cls}" src="assets/{name}.webp" alt="{alt}" loading="lazy" decoding="async">'
def page(name,title,body):
 nav=''.join(f'<a href="{f}.html"'+(' aria-current="page"' if name==f else '')+f'>{l}</a>' for f,l in NAV)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="The ’while brand guidelines. Explore the strategy, original identity, experience, and application rules."><meta name="theme-color" content="#FDFFEE"><meta name="robots" content="noindex, nofollow"><title>’while — {title}</title><link rel="icon" href="assets/apostrophe.svg" type="image/svg+xml"><link rel="preload" href="assets/chubbo-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="assets/national-park-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="styles.css"><script src="data.js" defer></script><script src="app.js" defer></script></head>
<body data-page="{name}"><a class="skip" href="#main">Skip to content</a>
<header class="site-header"><div class="header-inner"><a class="brand" href="index.html" aria-label="’while guidelines home"><img src="assets/while-logo.svg" alt="’while" width="560" height="177"></a><nav aria-label="Main navigation" id="main-nav">{nav}</nav><div class="header-actions"><button class="search-open icon-button" aria-label="Find a guideline" aria-haspopup="dialog"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg></button><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false">Menu <span aria-hidden="true">+</span></button></div></div></header>
<main id="main" class="{'home' if name=='index' else 'container'}">{body}</main>
<footer class="site-footer container"><a href="index.html" aria-label="’while guidelines home"><img src="assets/while-logo.svg" alt="’while" width="560" height="177"></a><a href="toolkit.html#downloads">Brand Assets <span aria-hidden="true">↗</span></a></footer>
<dialog id="search-dialog" aria-labelledby="search-title"><div class="dialog-head"><h2 id="search-title">Find a guideline.</h2><button class="icon-button close-dialog" aria-label="Close search">×</button></div><label class="sr-only" for="guide-search">Search brand rules and applications</label><input id="guide-search" type="search" placeholder="Try apostrophe, color, Aesop…" autocomplete="off"><div id="search-results" aria-live="polite"></div><p class="fine-print">Search across all chapters. Press Escape to close.</p></dialog>
<div id="toast" role="status" aria-live="polite"></div></body></html>'''

home='''<section class="home-opening container"><div class="home-kicker"><p class="eyebrow">’while / Brand Guidelines</p><a href="toolkit.html#downloads" class="text-link">Get the Guidelines <span aria-hidden="true">↗</span></a></div><div class="home-title"><h1>A shared way<br>to create.</h1></div><figure class="home-image"><img src="assets/interior.webp" alt="The ’while interior with intimate tables, upholstered seating, warm light, and a visible service counter" fetchpriority="high"></figure></section><section class="home-contents container"><div class="contents-intro"><p class="eyebrow">A Practical Reference</p><h2>Contents</h2><p>Begin with the foundation, then choose the rules and examples for the work in front of you.</p></div><div class="chapter-list">'''
for i,(f,t,d) in enumerate([('brand','The Brand','Purpose, people, and voice'),('identity','Identity','Logo, color, and typography'),('graphics','Graphic Language','Patterns, layout, and imagery'),('experience','Experience','Service, space, and the senses'),('applications','Applications','The identity in the world'),('toolkit','Toolkit','Prompts, review, and assets')],1):
 home+=f'<a href="{f}.html"><span class="chapter-number">0{i}</span><div><h3>{t}</h3><p>{d}</p></div><span class="chapter-arrow" aria-hidden="true">↗</span></a>'
home+='</div></section><section class="home-note"><div class="container"><h2>Make room for the details.</h2><a class="button" href="identity.html">Explore the Identity <span aria-hidden="true">→</span></a></div></section>'
(D/'index.html').write_text(page('index','Brand Guidelines',home))

brand=intro('01','The Brand','An after-dinner ritual.','Italian gelato and wine, served in three small pairings. A bright opening, a creamy middle, and a lingering finish—with room for conversation between them.')
brand+=section('purpose','Our Foundation','Dessert is a reason to stay.','''<div class="reading"><h3>Purpose</h3><p>To turn dessert into a social pause.</p><h3>Vision</h3><p>To make an unhurried dessert experience a familiar way to continue the evening.</p><h3>Mission</h3><p>We create thoughtful gelato and Italian wine pairings, served one course at a time, with room for conversation between them.</p></div>''')
brand+=section('audience','People & Positioning','For a little more time.','''<div class="two-col"><article><h3>Who It’s For</h3><p>Adults aged 35 and older, especially couples and close friends who want to continue spending time together after dinner. Curious about wine, they value thoughtful food, comfortable surroundings, and conversation.</p></article><article><h3>A Coursed Ice Cream Bar</h3><p>A seated, gelato-led experience that brings the structure of a tasting menu to an intimate after-dinner occasion. Small Italian wine pairings arrive sequentially, giving each course its own moment.</p></article></div>''')
brand+='''<section class="manifesto" id="manifesto"><p class="eyebrow">Our Manifesto</p><div><h2>We believe the evening<br>deserves a little more time.</h2><div class="reading"><p>Time to notice a new flavor, linger over a conversation, and enjoy the company across the table. Some of the moments we want to keep happen after the plates have been cleared, when there is still more to say.</p><p>’while makes room for those moments. Italian gelato and wine come together in three thoughtful courses: a cool spoonful, a small sip, and a pause to see how the flavors unfold.</p><p>Come with curiosity. We’ll take care of the details.</p><p class="tagline">Take Your Sweet Time.</p></div></div></section>'''
brand+=section('values','VALUES','Time. Craft. Comfort.','''<div class="three-col values"><article><span class="eyebrow">01</span><h3>Time</h3><p>Sequential service, spacious compositions, and gentle transitions give each moment time to be noticed.</p></article><article><span class="eyebrow">02</span><h3>Craft</h3><p>Every pairing and material is chosen with intention. Flavor, typography, ceramics, and finishing details work together.</p></article><article><span class="eyebrow">03</span><h3>Comfort</h3><p>Familiar language, clear information, and intimate seating make discovery feel easy, regardless of wine knowledge.</p></article></div>''')
brand+=section('voice','Personality & Voice','The effortless host.','''<p class="lead">Thoughtful, warm, and unhurried.</p><p class="reading">’while anticipates what guests need and offers gentle guidance at the right moment. Every detail is considered, while the experience feels easy.</p><div class="voice-list"><p><span>Concise</span>Stay for another taste.</p><p><span>Suggestive</span>Try the gelato, then the wine. Notice what changes.</p><p><span>Pairing-led</span>Bright citrus meets gentle bubbles.</p></div>''')
brand+=section('formats','Service Formats','One ritual. Four ways to enter.','''<div class="two-col rules"><article><h3>Pairing Menu for Two</h3><p>The signature three-course experience for two guests, served one pairing at a time.</p></article><article><h3>Seasonal Pairing Menu</h3><p>Three new courses built from seasonal gelato while retaining the same paced structure.</p></article><article><h3>Single Pair</h3><p>A shorter entry into the experience for guests choosing one pairing.</p></article><article><h3>Zero-Proof Pairing Menu</h3><p>The same three-course framework without alcohol. Specific pairings must be confirmed.</p></article></div><a class="text-link" href="experience.html#sequence">Explore the Three-Course Sequence →</a>''')
(D/'brand.html').write_text(page('brand','The Brand',brand))

identity=intro('02','Identity','Keep the character.','The custom apostrophe, rounded contours, warm palette, and two type families work as one system. Use the original artwork, and let the details stay familiar.')
identity+=section('logo','The Original Artwork','One fixed composition.','''<p class="reading">The custom apostrophe and wordmark form one unit. Preserve letterforms, spacing, proportions, and the relationship between them. Never recreate the logo by typing the brand name.</p><div class="specimen-tools"><div class="segmented" aria-label="Logo background"><button data-surface="cream" aria-pressed="true">Cream</button><button data-surface="orange" aria-pressed="false">Orange</button><button data-surface="charcoal" aria-pressed="false">Charcoal</button></div><label class="check-label"><input type="checkbox" id="clear-space"> Show Clear Space</label></div><div class="logo-stage" id="logo-stage" data-surface="cream"><div class="protected-logo"><span class="original-logo" role="img" aria-label="Original ’while wordmark with custom apostrophe"></span><span class="space-unit">x = apostrophe height</span></div></div><div class="specimen-caption"><p>Use the apostrophe height as the clear-space unit around the horizontal wordmark.</p><a href="assets/while-logo.svg" download="while-original-logo.svg">Original SVG ↗</a></div>''')
identity+=section('variations','Approved Variations','Choose the right form.','''<div class="two-col sheets"><figure><img src="assets/logo-variations-centered.svg" width="304" height="196" alt="Approved horizontal, filled, and outlined ’while logo variations" loading="lazy"><figcaption>Horizontal marks for compact signatures. Organic variations for labels, charms, and larger brand moments.</figcaption></figure><figure><img src="assets/while-logo-color-variations.svg" alt="Six approved ’while logo color variations on cream, orange, and charcoal backgrounds" width="1744" height="990" loading="lazy"><figcaption>Select an approved color version with clear separation from its background. Preserve the complete mark.</figcaption></figure></div>''')
identity+=section('misuse','Protect the Identity','Small changes change the mark.','''<div class="misuse-grid"><article><div class="misuse-image stretched"><img src="assets/while-logo.svg" alt="Incorrect example: a stretched wordmark"></div><h3>Do Not Stretch</h3><p>Scale the supplied artwork proportionally.</p></article><article><div class="misuse-image retyped" aria-label="Incorrect example: a retyped brand name">’while</div><h3>Do Not Retype</h3><p>Chubbo supports headlines. It does not replace the logo.</p></article><article><div class="misuse-image changed"><img src="assets/while-logo.svg" alt="Incorrect example: the custom apostrophe has been removed"></div><h3>Do Not Alter the Apostrophe</h3><p>Keep its original contour and relationship to the letters.</p></article><article><div class="misuse-image effects"><img src="assets/while-logo.svg" alt="Incorrect example: a drop shadow on the wordmark"></div><h3>Do Not Add Effects</h3><p>Avoid shadows, gradients, outlines, and decorative additions.</p></article></div><div class="inline-note"><h3>Do Not Rearrange</h3><p>Use the approved compositions rather than creating new letter arrangements.</p></div><div class="two-col rules"><article><h3>Test the Final Size</h3><p>The PDF includes 2.50, 1.75, 1.25, and 0.88 inch print test sizes. These are test sizes, not approved minimums. Print at Actual Size and check the apostrophe, counters, and fine details on the final stock.</p></article><article><h3>Co-Brand with Care</h3><p>Match perceived visual weight, preserve both official artworks, and retain their clear space. Equal emphasis does not require equal bounding boxes. Caption Aesop and Slowear concepts as speculative collaborations.</p></article></div>''')
identity+=section('color','The Palette','Warmth, with clarity.','''<div class="swatches"><button class="swatch orange" data-copy="#FF9A3E" aria-label="Copy Warm Orange hex FF9A3E"><span>Warm Orange</span><strong>#FF9A3E</strong><small>RGB 255 · 154 · 62 <span>Copy ↗</span></small></button><button class="swatch cream" data-copy="#FDFFEE" aria-label="Copy Soft Cream hex FDFFEE"><span>Soft Cream</span><strong>#FDFFEE</strong><small>RGB 253 · 255 · 238 <span>Copy ↗</span></small></button><button class="swatch charcoal" data-copy="#3D3535" aria-label="Copy Deep Charcoal hex 3D3535"><span>Deep Charcoal</span><strong>#3D3535</strong><small>RGB 61 · 53 · 53 <span>Copy ↗</span></small></button></div><div class="contrast-tool"><div><h3>Check a Combination</h3><p>Use charcoal on cream or orange for essential text. Orange on cream is reserved for nonessential graphic moments.</p><div class="field-row"><label>Text<select id="contrast-fg"><option value="#3D3535">Deep Charcoal</option value="#FF9A3E">Warm Orange</option><option value="#FDFFEE">Soft Cream</option></select></label><label>Background<select id="contrast-bg"><option value="#FDFFEE">Soft Cream</option><option value="#FF9A3E">Warm Orange</option><option value="#3D3535">Deep Charcoal</option></select></label></div></div><div id="contrast-preview"><p class="tagline">Take Your Sweet Time.</p><div id="contrast-result" aria-live="polite"></div></div></div><p class="fine-print">Digital text baseline: 4.5:1 for normal text, 3:1 for large text. Logo artwork is exempt but must remain recognizable. Check print conversions with a physical proof on the chosen stock.</p>''')
identity+=section('typography','Two Type Families','A considered contrast.','''<div class="two-col type-specimens"><article class="orange"><p class="eyebrow">Display</p><h3>Chubbo</h3><p class="alphabet chubbo">Aa Bb Cc<br>0123456789</p><p>Headlines, expressive statements,<br>and course names.</p></article><article class="charcoal"><p class="eyebrow">Functional</p><h3>National Park</h3><p class="alphabet national">Aa Bb Cc<br>0123456789</p><p>Body text, navigation, labels,<br>and the tagline.</p></article></div><div class="type-tool"><div class="field-row"><label class="grow">Try a Line<input id="type-input" maxlength="120" value="A little at a time."></label><label>Typeface<select id="type-family"><option value="Chubbo">Chubbo</option><option value="National">National Park</option></select></label><label>Size <output id="type-size-value">52 px</output><input id="type-size" type="range" min="24" max="80" value="52"></label></div><div id="type-preview">A little at a time.</div><p id="type-role" class="fine-print">Chubbo / Display, headlines, and course names</p></div>''')
(D/'identity.html').write_text(page('identity','Identity',identity))

graphics=intro('03','Graphic Language','A measured rhythm.','Supporting forms, spacious grids, and warm photography give the identity room to move. Keep each choice connected to the original artwork.')
graphics+=section('patterns','Supporting Assets','One contour. Three approaches.','''<div class="pattern-selector segmented" aria-label="Pattern example"><button data-pattern="spaced" aria-pressed="true">Spaced Repeat</button><button data-pattern="paired" aria-pressed="false">Paired Forms</button><button data-pattern="cropped" aria-pressed="false">Cropped Contour</button></div><figure class="pattern-preview"><img id="pattern-image" src="assets/pattern-spaced.svg" alt="Spaced Repeat: cream apostrophe forms in a measured grid on charcoal"><figcaption id="pattern-caption" aria-live="polite"><h3>A Measured Rhythm.</h3><p>Unit height h; horizontal pitch 2.2h; vertical pitch 2.1h. Keep all units at one scale and orientation. Use on tissue, packaging interiors, and tray liners.</p></figcaption></figure><a class="text-link" id="pattern-download" href="assets/pattern-spaced.svg" download>Download the Reference SVG ↗</a>''')
graphics+=section('layout','Layout & Grid','Give the content space.','''<div class="section-toolbar"><p>12 columns on desktop. 4 columns on mobile.</p><button class="button" id="grid-toggle" aria-pressed="false">Show Grid <span aria-hidden="true">+</span></button></div><div class="grid-demo" id="grid-demo"><div><span class="eyebrow">Statement + Image</span><h3>A little<br>at a time.</h3><p>Three small courses, brought to your table one at a time.</p><p class="tagline">Take Your Sweet Time.</p></div>'''+image('charm','A small serving of gelato in a metal coupe with the original orange ’while glass charm')+'''<div class="grid-lines" aria-hidden="true">'''+('<span></span>'*12)+'''</div></div><div class="three-col layout-notes"><article><h3>Statement + Image</h3><p>One expressive headline and one calm photograph.</p></article><article><h3>Information + Detail</h3><p>A full-width reading column with a supporting detail.</p></article><article><h3>Three-Course Sequence</h3><p>Equal containers with consistent title, description, and progress positions.</p></article></div><p class="fine-print">Use approximately 5% desktop side margins. Start with 24 px mobile side margins and 16 px gutters. Stack sections in content order and choose breakpoints by content fit. Keep the complete logo visible.</p>''')
graphics+=section('photography','Image Direction','Human scale. Warm light.','''<figure>'''+image('interior','Warm natural light across small tables and tactile materials in the ’while interior')+'''<figcaption>Real materials. Gentle shadows. Room for conversation.</figcaption></figure><p class="lead">Show small servings, natural gestures, intimate tables, and tactile details.</p><p class="reading">Use believable textures, warm light, gentle shadows, and uncluttered compositions. Let the serving size and the space feel comfortable and real.</p>''')
(D/'graphics.html').write_text(page('graphics','Graphic Language',graphics))

experience=intro('04','Experience','Make the pause tangible.','Every touchpoint supports a comfortable progression, from the first welcome to something taken home. The ritual unfolds one pairing at a time.')
experience+=section('journey','The Guest Journey','A little more time, together.','''<ol class="journey"><li><h3>Arrive</h3><p>Understand the offer through the entrance, signage, and welcome.</p></li><li><h3>Settle In</h3><p>Feel comfortable through seating, materials, and a clear menu.</p></li><li><h3>Discover</h3><p>Experience three pairings sequentially, with room to notice.</p></li><li><h3>Linger</h3><p>Let the final taste and conversation continue.</p></li><li><h3>Take It with You</h3><p>Carry the ritual home through packaging and selected objects.</p></li></ol>''')
experience+=section('sequence','The Three-Course Sequence','A little at a time.','''<p class="reading">Explore how the names, pairings, and mood progress. Present one course at a time, keeping information and controls in consistent positions.</p><div class="tasting" id="tasting" tabindex="0" aria-label="Three-course pairing explorer. Use left and right arrow keys to change courses."><div class="tasting-head"><span class="eyebrow">The Pairing Ritual</span><span id="course-count">01 / 03</span></div><div id="course-content" aria-live="polite" aria-atomic="true"></div><div class="course-bottom"><div class="course-progress" aria-label="Course progress"></div><div class="course-controls"><button class="button on-dark" id="course-prev">← Previous</button><button class="button cream-button" id="course-next">Next Course →</button></div></div></div>''')
experience+=section('senses','Material & Senses','Consider every touchpoint.','''<div class="two-col sensory"><article><span class="eyebrow">Material & Touch</span><h3>Make the Identity Tangible.</h3><p>Terracotta, ceramic serving pieces, textiles, and wine glass charms connect the brand to objects guests touch. Each detail should support comfort, recognition, or interaction.</p><p class="fine-print">Prototype charm dimensions, material, attachment, edge finish, weight, and cleaning.</p></article><article><span class="eyebrow">Sound</span><h3>Leave Room for Conversation.</h3><p>Piero Piccioni instrumental film scores are the supplied reference direction. Curate gentle cinematic jazz, avoid abrupt changes, and keep conversation intelligible.</p></article><article><span class="eyebrow">Scent</span><h3>Flavors First. Scents After.</h3><p>The Aesop concept belongs in a separate hand-washing area. Keep the active tasting space free of ambient fragrance.</p><a class="text-link" href="applications.html#aesop">Explore the Aesop Concept ↗</a></article><article><span class="eyebrow">Spatial Direction</span><h3>Intimate by Design.</h3><p>Small tables, comfortable seating, warm materials, visible service, and restrained signage give the ritual a permanent setting.</p></article></div>''')
(D/'experience.html').write_text(page('experience','Experience',experience))

applications=intro('05','Applications','The identity in the world.','Choose a touchpoint to see what stays fixed and what can adapt. These are design concepts; the Aesop and Slowear collaborations are speculative.')
applications+='''<section id="application-library" class="application-library"><div class="filter-bar" aria-label="Filter applications"></div><p class="eyebrow result-count" id="app-count" aria-live="polite"></p><div id="applications-grid" class="applications-grid"></div></section><dialog id="application-dialog" aria-labelledby="application-title"><div class="dialog-head"><span class="eyebrow">Application Guide</span><button class="icon-button close-dialog" aria-label="Close application">×</button></div><div id="application-content"></div></dialog>'''
(D/'applications.html').write_text(page('applications','Applications',applications))

toolkit=intro('06','Toolkit','Human direction.<br>AI execution.','Start with the established brand foundation. Define the application, choose what can adapt, then review every output against the original identity.')
toolkit+=section('working-rules','The Creative Agreement','Permanent / flexible.','''<div class="two-col"><article><h3>Permanent</h3><p>Purpose, audience, values, approved logos, colors, typography, voice, and asset-fidelity requirements.</p></article><article><h3>Flexible</h3><p>Application, composition, image crop, scale, placement, camera position, deliverable format, and context-specific production needs.</p></article></div><div class="three-col tool-roles"><article><h3>Text Assistance</h3><p>Briefs, copy drafts, and prompt structure. Review meaning and voice.</p></article><article><h3>Image Generation</h3><p>Atmosphere and application studies. Review fidelity and realism.</p></article><article><h3>Code Assistance</h3><p>Layouts and interactions. Test behavior and accessibility.</p></article></div>''')
toolkit+=section('prompt-builder','Reusable Prompt','Build from the foundation.','''<div class="prompt-builder"><div class="field-row"><label class="grow">Application<select id="prompt-application"></select></label><label class="check-label"><input type="checkbox" id="include-foundation" checked> Include Brand Foundation</label></div><label class="block-label" for="project-context">Project Details <span class="optional">Optional</span></label><textarea id="project-context" rows="3" maxlength="2000" placeholder="Add the format, views, dimensions, or context you need."></textarea><div class="section-toolbar prompt-actions"><p>Foundation → Brief → Direction → Deliverables → Review</p><button class="button" id="copy-prompt">Copy Prompt ↗</button></div><pre id="prompt-output" tabindex="0" aria-label="Generated reusable prompt"></pre><button class="text-button" id="download-prompt">Download Prompt as TXT ↗</button></div>''')
checks=['Original logos and proportions preserved.','Authentic Chubbo and National Park applied.','Approved palette and readable contrast checked.','Course order and project-specific rules verified.','Images checked for plausible scale and materials.','No invented facts or unsupported product claims.','Speculative collaborations clearly identified.','Print proof and final designer review completed.']
toolkit+=section('review','Review Checklist','Before release.','''<p class="reading">Review the work against the brand, technical, accessibility, and factual criteria. Your checked items stay in this browser.</p><div class="review-top"><span id="review-progress" aria-live="polite">0 of 8 checked</span><button class="text-button" id="reset-review">Reset</button></div><progress id="review-meter" value="0" max="8" aria-label="Review checklist completion"></progress><div class="review-list">'''+''.join(f'<label class="review-item"><input type="checkbox" data-review="{i}"><span>{t}</span></label>' for i,t in enumerate(checks))+'''</div>''')
toolkit+=section('downloads','Source Assets','Begin with the originals.','''<div class="download-list"><a href="assets/while-brand-guidelines.pdf?v=75fc9f752374" download="while-brand-guidelines-spreads.pdf"><span>Brand Guidelines PDF<small>The complete supplied reference · spread layout</small></span><span aria-hidden="true">↓</span></a><a href="assets/while-logo.svg" download="while-original-logo.svg"><span>Original Wordmark<small>Vector SVG · custom apostrophe intact</small></span><span aria-hidden="true">↓</span></a><a href="assets/logo-variations.svg" download><span>Approved Logo Variations<small>Vector reference sheet</small></span><span aria-hidden="true">↓</span></a><a href="assets/chubbo-regular.ttf" download><span>Chubbo<small>Authentic regular font file · display typography</small></span><span aria-hidden="true">↓</span></a><a href="assets/national-park-regular.ttf" download><span>National Park<small>Authentic regular font file · body, navigation, labels, and tagline</small></span><span aria-hidden="true">↓</span></a></div>''')
(D/'toolkit.html').write_text(page('toolkit','Toolkit',toolkit))
# Search actual authored chapter text, with deep links to each rule.
from html.parser import HTMLParser
class Index(HTMLParser):
 def __init__(self):super().__init__();self.items=[];self.current=None;self.capture=False;self.title=False
 def handle_starttag(self,t,a):
  a=dict(a)
  if t=='section' and a.get('id'):
   self.current={'file':self.file+'#'+a['id'],'title':'','text':''};self.items.append(self.current)
  if self.current and t in ('h2','h1') and not self.current['title']:self.title=True
 def handle_endtag(self,t):
  if t in ('h1','h2'):self.title=False
  if t=='section':self.current=None
 def handle_data(self,s):
  if self.current:
   self.current['text']+=' '+s.strip()
   if self.title:self.current['title']+=s
index=[]
for name,title in NAV:
 p=Index();p.file=name+'.html';p.feed((D/(name+'.html')).read_text());index.extend(p.items)
index=[item for item in index if item['title'].strip()]
index.append({'file':'applications.html','title':'Application Library','text':'Store interior Wine glass charms Charm construction Wine expo Mobility branding Slowear Aesop Wine-infused gelato Speculative collaborations Packaging Original logo National Park tagline'})
(D/'search-index.json').write_text(json.dumps(index,ensure_ascii=False))
print('Generated 7 chapters and the search index.')
